#!/usr/bin/env python3
import sys, os
import numpy as np

def calcat(cordf, comf, wrcf, catfchk, eout, method): 
    #cordf coordinates of neutral dynamic
    #comf cation comfile without the .com ending !!!!
    #wrcf write coordinates filename
    #cafchk name of cation fchk file
    #eout read neutral SCF Energy in first col, write cat SCF in 2nd col, write IP in 3rd col
    with open(cordf) as f:
        data = f.readlines()
    write = True
    count = 0
    sc = 0
    while write==True:
        with open(wrcf, 'w') as g:
            #write cat xyz-file
            atn = int(data[count])
            for i in range(atn):
                g.write(data[count+i+2])
            count+=atn+2
        if len(data) < count+2:
            write = False
        #get IP 
        os.system('g16 {0}.com {0}.log'.format(comf))
        os.system('formchk {0}.chk {0}.fchk'.format(catfchk)) #formchk forcecat.chk forcecat
        os.system('date >> time.txt')
        try: 
            scfcat = float(get_e('{}.fchk'.format(catfchk), '{} Energy'.format(method[1])))
        except: 
            scfcat = None
        with open(eout) as h:
            ipd = h.readlines()
        with open(eout, 'w') as h:
            scfneut=float(ipd[sc].split('\n')[0].split('\t')[1])
            time = float(ipd[sc].split('\n')[0].split('\t')[0])
            for i in range(len(ipd)):
                if i == sc:
                    if scfcat == None: 
                        h.write('{0}\t{1}\tNone\tNone\n'.format(time, scfneut))
                    else: 
                        h.write('{0}\t{1}\t{2}\t{3}\n'.format(time, scfneut, scfcat, scfcat-scfneut))
                else:
                    h.write(ipd[i])
        sc +=1 

def get_e(filen, search):
    with open(filen) as f:
        a = f.readlines()
        for i in a:
            if search in i:
                return(float(i.split(' ')[-1]))

def get_in(ending):
    files = os.listdir()
    for i in files:
        if ending in i:
            return i

def get_ip(an, ne):
    with open(an) as f:
        a = f.readlines()
        anE = 0
        for i in a:
            if 'SCF Done' in i:
                anE = float(i.split('  ')[2])
        neE = float(np.loadtxt(ne)[0][1])

def anic(dyn, free=0):
    with open(dyn) as f:
        natoms = int(f.readline())
        coord = f.readlines()
        with open('coord.xyz', 'w+') as g:
            for j in range(natoms):
                g.write(coord[j+free])
